[metadata] {"type": "create", "filePath": "/root/.agent/diagrams/energy-transition-timeline.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Global Energy Transition: Dual-Track Timeline 2000–2035</title>
<link href="https://fonts.googleapis.com/css2?family=Crimson+Pro:ital,wght@0,400;0,600;0,700;1,400&family=IBM+Plex+Mono:wght@400;500&family=IBM+Plex+Sans:wght@400;500;600&display=swap" rel="stylesheet">
<style>
:root {
  --bg: #f8f5f0;
  --surface: #ffffff;
  --surface-2: #f1ede7;
  --border: rgba(40,30,20,0.12);
  --text: #1a1410;
  --text-dim: #5a4f44;
  --text-muted: #8a7d72;

  /* fossil track colors */
  --coal: #3d2b1f;
  --oil: #7a4a1a;
  --gas: #b87333;

  /* clean track colors */
  --solar: #c27d0e;
  --wind: #2a6e5c;
  --hydrogen: #1e4d7a;

  /* inflection zone */
  --inflection-bg: rgba(200, 120, 30, 0.06);
  --inflection-border: rgba(200, 120, 30, 0.3);

  /* share line */
  --share-line: #1e4d7a;
  --share-fill: rgba(30, 77, 122, 0.08);

  /* track bands */
  --clean-band: rgba(42, 110, 92, 0.06);
  --fossil-band: rgba(61, 43, 31, 0.06);

  --radius: 3px;
  --mono: 'IBM Plex Mono', monospace;
  --sans: 'IBM Plex Sans', sans-serif;
  --serif: 'Crimson Pro', Georgia, serif;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

body {
  background: var(--bg);
  font-family: var(--sans);
  color: var(--text);
  min-height: 100vh;
  padding: 40px 32px 60px;
}

.page-header {
  max-width: 960px;
  margin: 0 auto 36px;
  border-bottom: 1.5px solid var(--border);
  padding-bottom: 20px;
}

.kicker {
  font-family: var(--mono);
  font-size: 10px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--text-muted);
