  { year: 2022, track: "clean",  sub_type: "solar",    significance: 8, event: "Global solar annual additions exceed 200 GW" },
  { year: 2022, track: "fossil", sub_type: "coal",     significance: 8, event: "G7 pledges to end unabated coal power by 2035" },
  { year: 2022, track: "fossil", sub_type: "gas",      significance: 7, event: "EU energy crisis revives LNG debate vs renewables" },
  { year: 2023, track: "clean",  sub_type: "wind",     significance: 8, event: "China installs record 20 GW offshore wind in single year" },
  { year: 2023, track: "clean",  sub_type: "hydrogen", significance: 7, event: "NEOM green hydrogen mega-project breaks ground" },
  { year: 2023, track: "fossil", sub_type: "oil",      significance: 9, event: "IEA declares peak oil demand expected before 2030" },
  { year: 2024, track: "clean",  sub_type: "solar",    significance: 9, event: "Solar PV surpasses 2 TW cumulative global capacity" },
  { year: 2024, track: "fossil", sub_type: "coal",     significance: 6, event: "India retires first wave of subcritical coal plants" },
  { year: 2025, track: "clean",  sub_type: "hydrogen", significance: 7, event: "First commercial-scale green H2 export terminal operational" },
  { year: 2025, track: "fossil", sub_type: "gas",      significance: 6, event: "Major pension funds divest from new gas exploration" },
];

const shareData = [
  { year: 2000, pct: 19.2 }, { year: 2002, pct: 19.5 }, { year: 2004, pct: 19.8 },
  { year: 2006, pct: 20.3 }, { year: 2008, pct: 20.9 }, { year: 2010, pct: 21.7 },
  { year: 2012, pct: 23.1 }, { year: 2014, pct: 24.8 }, { year: 2015, pct: 25.6 },
  { year: 2016, pct: 26.5 }, { year: 2017, pct: 27.4 }, { year: 2018, pct: 28.6 },
  { year: 2019, pct: 29.8 }, { year: 2020, pct: 31.5 }, { year: 2021, pct: 32.8 },
  { year: 2022, pct: 34.6 }, { year: 2023, pct: 37.2 }, { year: 2024, pct: 39.8 },
  { year: 2025, pct: 42.0 }, { year: 2027, pct: 46.5 }, { year: 2030, pct: 52.0 },
  { year: 2033, pct: 57.5 }, { year: 2035, pct: 62.0 },
];

const COLORS = {
  coal: '#3d2b1f', oil: '#9b5e1f', gas: '#c88844',
  solar: '#c27d0e', wind: '#2a6e5c', hydrogen: '#1e4d7a'
};
const INFLECTION_START = 2015;
const INFLECTION_END = 2025;

// ─── CANVAS SETUP ────────────────────────────────────────────────────────────
const canvas = document.getElementById('mainChart');
const dpr = window.devicePixelRatio || 1;

function draw() {
  const container = canvas.parentElement;
  const W = container.clientWidth;
  const H = Math.round(W * 0.62); // golden-ish ratio

  canvas.width = W * dpr;
  canvas.height = H * dpr;
  canvas.style.width = W + 'px';
  canvas.style.height = H + 'px';

  const ctx = canvas.getContext('2d');
  ctx.scale(dpr, dpr);

  // Layout geometry
  const pad = { top: 44, right: 28, bottom: 58, left: 72 };
  const chartW = W - pad.left - pad.right;
  const chartH = H - pad.top - pad.bottom;

  const YEAR_MIN = 1999.5, YEAR_MAX = 2035.5;
  const SHARE_MIN = 15, SHARE_MAX = 68;

  // Divides chart: upper half = clean, lower half = fossil
  const axisY = pad.top + chartH / 2;
  const cleanBandH = chartH / 2;
  const fossilBandH = chartH / 2;

  function xOf(year) {
    return pad.left + (year - YEAR_MIN) / (YEAR_MAX - YEAR_MIN) * chartW;
  }
  // Share y maps to clean band (top half)
  function shareY(pct) {
    // map 15–68% to full chart height for visual clarity
    const norm = (pct - SHARE_MIN) / (SHARE_MAX - SHARE_MIN);
    return pad.top + chartH - norm * chartH;
  }
  function sigToR(sig) {
    return 4 + (sig - 3) * 1.9; // 3→4px, 9→15.4px
  }

  // ── Background bands ──
  ctx.fillStyle = 'rgba(42, 110, 92, 0.05)';
  ctx.fillRect(pad.left, pad.top, chartW, cleanBandH);
  ctx.fillStyle = 'rgba(61, 43, 31, 0.05)';
  ctx.fillRect(pad.left, axisY, chartW, fossilBandH);

  // ── Inflection zone ──
  const ix1 = xOf(INFLECTION_START);
  const ix2 = xOf(INFLECTION_END);
  ctx.fillStyle = 'rgba(194, 125, 14, 0.08)';
  ctx.fillRect(ix1, pad.top, ix2 - ix1, chartH);
  // Inflection zone border lines
  ctx.save();
  ctx.setLineDash([4, 4]);
  ctx.strokeStyle = 'rgba(194, 125, 14, 0.5)';
  ctx.lineWidth = 1;
  ctx.beginPath(); ctx.moveTo(ix1, pad.top - 4); ctx.lineTo(ix1, pad.top + chartH + 4); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(ix2, pad.top - 4); ctx.lineTo(ix2, pad.top + chartH + 4); ctx.stroke();
  ctx.restore();
  // Inflection label
  ctx.fillStyle = 'rgba(194, 125, 14, 0.8)';
  ctx.font = `500 9px 'IBM Plex Mono', monospace`;
  ctx.textAlign = 'center';
  ctx.fillText('INFLECTION ZONE', (ix1 + ix2) / 2, pad.top - 6);

  // ── Y-axis grid lines & share scale ──
  const shareTicks = [20, 25, 30, 35, 40, 45, 50, 55, 60];
  ctx.save();
  ctx.setLineDash([2, 4]);
  ctx.strokeStyle = 'rgba(30,77,122,0.15)';
  ctx.lineWidth = 0.8;
  shareTicks.forEach(pct => {
    const sy = shareY(pct);
    if (sy >= pad.top && sy <= pad.top + chartH) {
      ctx.beginPath();
      ctx.moveTo(pad.left, sy);
      ctx.lineTo(pad.left + chartW, sy);
      ctx.stroke();
      ctx.fillStyle = 'rgba(30,77,122,0.55)';
      ctx.font = `400 9px 'IBM Plex Mono', monospace`;
      ctx.textAlign = 'right';
      ctx.fillText(pct + '%', pad.left - 5, sy + 3.5);
    }
  });
  ctx.restore();

  // Y-axis label for share
  ctx.save();
  ctx.fillStyle = '#1e4d7a';
  ctx.font = `400 9px 'IBM Plex Mono', monospace`;
  ctx.textAlign = 'center';
  ctx.translate(13, pad.top + chartH / 2);
  ctx.rotate(-Math.PI / 2);
  ctx.fillText('Clean electricity share', 0, 0);
  ctx.restore();

  // ── Central axis (year line) ──
  ctx.strokeStyle = 'rgba(40,30,20,0.25)';
  ctx.lineWidth = 1.2;
  ctx.beginPath();
  ctx.moveTo(pad.left, axisY);
  ctx.lineTo(pad.left + chartW, axisY);
  ctx.stroke();

  // ── Year tick marks & labels ──
  const years = [2000, 2005, 2010, 2015, 2020, 2025, 2030, 2035];
  ctx.fillStyle = 'rgba(40,30,20,0.5)';
  ctx.font = `400 9.5px 'IBM Plex Mono', monospace`;
  ctx.textAlign = 'center';
  years.forEach(y => {
    const x = xOf(y);
    ctx.strokeStyle = 'rgba(40,30,20,0.2)';
    ctx.lineWidth = 0.8;
    ctx.beginPath();
    ctx.moveTo(x, axisY - 4);
    ctx.lineTo(x, axisY + 4);
    ctx.stroke();
    ctx.fillStyle = 'rgba(40,30,20,0.55)';
    ctx.fillText(y, x, pad.top + chartH + 16);
  });

  // ── Projection marker (2024→) ──
  const projX = xOf(2024.5);
  ctx.save();
  ctx.setLineDash([3, 3]);
  ctx.strokeStyle = 'rgba(40,30,20,0.25)';
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(projX, pad.top);
  ctx.lineTo(projX, pad.top + chartH);
  ctx.stroke();
  ctx.restore();
  ctx.fillStyle = 'rgba(40,30,20,0.35)';
  ctx.font = `400 8.5px 'IBM Plex Mono', monospace`;
  ctx.textAlign = 'left';
  ctx.fillText('projected →', projX + 3, pad.top + 11);

  // ── Track band labels ──
  ctx.save();
  ctx.fillStyle = 'rgba(42,110,92,0.55)';
  ctx.font = `500 9px 'IBM Plex Mono', monospace`;
  ctx.textAlign = 'right';
  const cleanLabelY = pad.top + cleanBandH / 2;
  ctx.save();
  ctx.translate(pad.left - 8, cleanLabelY);
  ctx.rotate(-Math.PI / 2);
  ctx.textAlign = 'center';
  ctx.fillText('CLEAN', 0, 0);
  ctx.restore();

  ctx.fillStyle = 'rgba(61,43,31,0.55)';
  ctx.save();
  ctx.translate(pad.left - 8, axisY + fossilBandH / 2);
  ctx.rotate(-Math.PI / 2);
  ctx.textAlign = 'center';
  ctx.fillText('FOSSIL', 0, 0);
  ctx.restore();
  ctx.restore();

  // ── Share area fill ──
  ctx.save();
  ctx.beginPath();
  shareData.forEach((d, i) => {
    const sx = xOf(d.year);
    const sy = shareY(d.pct);
    if (i === 0) ctx.moveTo(sx, sy);
    else ctx.lineTo(sx, sy);
  });
  // Close to bottom of chart
  ctx.lineTo(xOf(shareData[shareData.length - 1].year), pad.top + chartH);
  ctx.lineTo(xOf(shareData[0].year), pad.top + chartH);
  ctx.closePath();
  ctx.fillStyle = 'rgba(30,77,122,0.07)';
  ctx.fill();
  ctx.restore();

  // ── Share line ──
  // Observed portion (up to 2024)
  ctx.save();
  ctx.beginPath();
  const observed = shareData.filter(d => d.year <= 2024);
  observed.forEach((d, i) => {
    const sx = xOf(d.year);
    const sy = shareY(d.pct);
    if (i === 0) ctx.moveTo(sx, sy);
    else ctx.lineTo(sx, sy);
  });
  ctx.strokeStyle = '#1e4d7a';
  ctx.lineWidth = 2.2;
  ctx.lineJoin = 'round';
  ctx.stroke();
  ctx.restore();

  // Projected portion (2024+)
  ctx.save();
  ctx.setLineDash([5, 4]);
  ctx.beginPath();
  const projected = shareData.filter(d => d.year >= 2024);
  projected.forEach((d, i) => {
    const sx = xOf(d.year);
    const sy = shareY(d.pct);
    if (i === 0) ctx.moveTo(sx, sy);
    else ctx.lineTo(sx, sy);
  });
  ctx.strokeStyle = '#1e4d7a';
  ctx.lineWidth = 2;
  ctx.lineJoin = 'round';
  ctx.stroke();
  ctx.restore();

  // Share value annotations at key years
  const shareAnnotations = [
    { year: 2000, label: '19.2%', offset: { x: 2, y: -8 } },
    { year: 2015, label: '25.6%', offset: { x: 0, y: -9 } },
    { year: 2020, label: '31.5%', offset: { x: 2, y: -9 } },
    { year: 2025, label: '42%', offset: { x: 2, y: -9 } },
    { year: 2035, label: '62%', offset: { x: -6, y: -9 } },
  ];
  shareAnnotations.forEach(a => {
    const d = shareData.find(s => s.year === a.year);
    if (!d) return;
    const sx = xOf(a.year) + a.offset.x;
    const sy = shareY(d.pct) + a.offset.y;
    ctx.fillStyle = '#1e4d7a';
    ctx.font = `500 8.5px 'IBM Plex Mono', monospace`;
    ctx.textAlign = 'center';
    ctx.fillText(a.label, sx, sy);
  });

  // ── Event markers ──
  // Group by year+track to stagger overlapping markers
  const grouped = {};
  events.forEach(ev => {
    const key = ev.year + '_' + ev.track;
    if (!grouped[key]) grouped[key] = [];
    grouped[key].push(ev);
  });

  // For tooltip tracking
  const markerRects = [];

  Object.entries(grouped).forEach(([key, evList]) => {
    const baseX = xOf(evList[0].year);
    const isClean = evList[0].track === 'clean';
    const bandH = chartH / 2;

    evList.forEach((ev, idx) => {
      const r = sigToR(ev.significance);
      const color = COLORS[ev.sub_type];

      // Vertical position within band: center of band, with offset for multiple events
      let yCenter;
      if (isClean) {
        // clean: above axis, band goes from pad.top to axisY
        // Center at 40% from bottom of band, stagger upward
        const bandCenter = axisY - bandH * 0.4;
        yCenter = bandCenter - idx * (r * 2 + 4);
        // Clamp to band
        yCenter = Math.max(pad.top + r + 2, Math.min(axisY - r - 4, yCenter));
      } else {
        // fossil: below axis, band goes from axisY to pad.top + chartH
        const bandCenter = axisY + bandH * 0.4;
        yCenter = bandCenter + idx * (r * 2 + 4);
        yCenter = Math.max(axisY + r + 4, Math.min(pad.top + chartH - r - 2, yCenter));
      }

      // Connector line from axis to marker
      ctx.save();
      ctx.strokeStyle = color + '50';
      ctx.lineWidth = 0.8;
      ctx.beginPath();
      ctx.moveTo(baseX, axisY + (isClean ? -2 : 2));
      ctx.lineTo(baseX, yCenter + (isClean ? r : -r));
      ctx.stroke();
      ctx.restore();

      // Marker circle
      ctx.save();
      ctx.beginPath();
      ctx.arc(baseX, yCenter, r, 0, Math.PI * 2);
      ctx.fillStyle = color;
      ctx.globalAlpha = 0.85;
      ctx.fill();
      ctx.strokeStyle = '#ffffff';
      ctx.lineWidth = 1;
      ctx.globalAlpha = 0.6;
      ctx.stroke();
      ctx.restore();

      // Significance label inside large markers
      if (ev.significance >= 8) {
        ctx.save();
        ctx.fillStyle = '#ffffff';
        ctx.font = `600 ${Math.round(r * 0.9)}px 'IBM Plex Mono', monospace`;
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText(ev.significance, baseX, yCenter);
        ctx.restore();
      }

      markerRects.push({
        x: baseX, y: yCenter, r,
        event: ev.event,
        year: ev.year,
        sub_type: ev.sub_type,
        significance: ev.significance,
        track: ev.track,
        color
      });
    });
  });

  // ── Axis label (year) ──
  ctx.fillStyle = 'rgba(40,30,20,0.5)';
  ctx.font = `400 9.5px 'IBM Plex Mono', monospace`;
  ctx.textAlign = 'center';
  ctx.fillText('Year', pad.left + chartW / 2, pad.top + chartH + 30);

  return { markerRects, pad, chartW, chartH, axisY, xOf, shareY };
}

// ─── TOOLTIP ─────────────────────────────────────────────────────────────────
let state = draw();

const tooltip = document.createElement('div');
tooltip.style.cssText = `
  position: fixed;
  background: #faf7f4;
  border: 1px solid rgba(40,30,20,0.18);
  border-radius: 3px;
  padding: 9px 12px;
  font-family: 'IBM Plex Sans', sans-serif;
  font-size: 12px;
  line-height: 1.5;
  color: #1a1410;
  pointer-events: none;
  box-shadow: 0 3px 12px rgba(0,0,0,0.1);
  max-width: 240px;
  z-index: 1000;
  display: none;
`;
document.body.appendChild(tooltip);

canvas.addEventListener('mousemove', e => {
  const rect = canvas.getBoundingClientRect();
  const mx = (e.clientX - rect.left);
  const my = (e.clientY - rect.top);

  let found = null;
  for (const m of state.markerRects) {
    const dx = mx - m.x, dy = my - m.y;
    if (Math.sqrt(dx*dx + dy*dy) <= m.r + 2) { found = m; break; }
  }

  if (found) {
    canvas.style.cursor = 'pointer';
    tooltip.style.display = 'block';
    tooltip.innerHTML = `
      <div style="font-family:'IBM Plex Mono',monospace;font-size:10px;letter-spacing:0.08em;text-transform:uppercase;color:${found.color};margin-bottom:4px;">
        ${found.year} · ${found.sub_type} · sig ${found.significance}
      </div>
      <div style="font-size:12px;color:#1a1410;line-height:1.45;">${found.event}</div>
      <div style="font-family:'IBM Plex Mono',monospace;font-size:9.5px;color:#8a7d72;margin-top:3px;">
        ${found.track === 'clean' ? '↑ Clean track' : '↓ Fossil retirement track'}
      </div>
    `;
    const tw = 240, th = 80;
    let tx = e.clientX + 14, ty = e.clientY - 20;
    if (tx + tw > window.innerWidth - 10) tx = e.clientX - tw - 14;
    if (ty + th > window.innerHeight - 10) ty = e.clientY - th - 10;
    tooltip.style.left = tx + 'px';
    tooltip.style.top = ty + 'px';
  } else {
    canvas.style.cursor = 'default';
    tooltip.style.display = 'none';
  }
});

canvas.addEventListener('mouseleave', () => {
  tooltip.style.display = 'none';
});

// ─── RESPONSIVE REDRAW ───────────────────────────────────────────────────────
let raf;
window.addEventListener('resize', () => {
  cancelAnimationFrame(raf);
  raf = requestAnimationFrame(() => { state = draw(); });
});
</script>
